            { id: 'side_quests', title: 'Complete {n} side quest(s)', icon: '<i class="ri-compass-3-line"></i>', field: 'sideQuestsCompleted', trackType: 'daily', defaults: { n: 2 }, options: [1, 2, 3, 5] }
